CREATE POLICY "Users can read own workspace images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'workspace-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can upload own workspace images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'workspace-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can update own workspace images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'workspace-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can delete own workspace images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'workspace-images' AND auth.uid()::text = (storage.foldername(name))[1]);